package org.springframework.samples.petclinic.rest.function.owner;

import java.time.DayOfWeek;
import java.time.LocalDate;
import java.util.Set;

/**
 * Business-day rules for owner registration on {@code POST /api/owners}. The effective registration
 * date must fall on a business day: when it is a Saturday, Sunday or a listed public holiday it rolls
 * forward to the next non-holiday weekday. The effective date is the one supplied in the request, or
 * the server's current date when the request omits it; either way the same roll-forward applies, so
 * every value derived from the registration date (the membership number's year segment, the per-day
 * create-limit bucket) is computed from the adjusted date.
 */
final class BusinessDay {

    /** Fixed public-holiday calendar; a date landing on one of these rolls forward. */
    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
            LocalDate.of(2026, 1, 1),
            LocalDate.of(2026, 1, 26),
            LocalDate.of(2026, 4, 25),
            LocalDate.of(2026, 12, 25),
            LocalDate.of(2026, 12, 28));

    private BusinessDay() {
    }

    /**
     * Rolls a date forward to the next non-holiday business day; a weekday that is not a public
     * holiday is returned unchanged. Weekends and listed public holidays are skipped, repeatedly, so
     * a holiday falling on (or adjacent to) a weekend still lands on a clear business day.
     */
    static LocalDate rollForward(LocalDate date) {
        while (isWeekend(date) || PUBLIC_HOLIDAYS.contains(date)) {
            date = date.plusDays(1);
        }
        return date;
    }

    private static boolean isWeekend(LocalDate date) {
        DayOfWeek dow = date.getDayOfWeek();
        return dow == DayOfWeek.SATURDAY || dow == DayOfWeek.SUNDAY;
    }

    /**
     * The effective, business-day registration date for a create: the supplied date when present,
     * otherwise the server's current date, rolled forward off any weekend.
     */
    static LocalDate effective(LocalDate supplied) {
        return rollForward(supplied != null ? supplied : LocalDate.now());
    }
}
